"""An interactive rework preview with shareable, non-personal planning choices."""
import shutil
from editorial import write_editorial_page


def add(out, origin, pages):
    root = out.parent
    for name in ('second-invoice.css', 'second-invoice.js', 'second-invoice-model.mjs'):
        shutil.copy(root / 'assets' / name, out / 'assets' / name)
    body = '''<div class="ripple-page">
    <header class="ripple-hero wrap"><div><a class="ripple-back" href="/explore/">Wazoozie / tools for a better first call</a><p class="ripple-kicker">A LITTLE FORESIGHT. A LOT LESS “AGAIN.”</p><h1>The Second<br><em>Invoice.</em></h1><p class="ripple-lede">See the work you could pay for twice.<br>Before you approve it once.</p><p>Pick up to four projects. Change their order. See where a finished job could get opened, patched or done again.</p><a class="ripple-jump" href="#ripple-lab">Try the example ↓</a></div><div class="ripple-hero-art" aria-hidden="true"><div class="ripple-orbit orbit-one"></div><div class="ripple-orbit orbit-two"></div><div class="ripple-orbit orbit-three"></div><div class="ripple-paper"><span>THE UNPLANNED SEQUEL</span><b>“We’ll need to<br>open that again.”</b><div class="ripple-paper-line"></div><p>Fresh paint. New access hole.<br>One conversation too late.</p><strong>Let’s rewind. ↶</strong></div><span class="ripple-art-label">SMALL DECISIONS. CONNECTED CONSEQUENCES.</span></div></header>
    <section class="wrap ripple-lab" id="ripple-lab" aria-labelledby="ripple-lab-title">
    <div class="ripple-section-heading"><div><p class="ripple-kicker">THE REWORK PREVIEW</p><h2 id="ripple-lab-title">What are you getting done?</h2></div><button type="button" class="ripple-quiet" id="ripple-clear">Start my own plan</button></div>
    <p id="ripple-mode">An example: paint, windows, then heating & cooling. Try changing the order.</p><div class="ripple-projects" id="ripple-projects" aria-label="Choose up to four projects"></div>
    <div class="ripple-workspace"><div class="ripple-left"><section class="ripple-order-panel"><div class="ripple-panel-head"><h3>Your proposed order</h3><span>Move a project ↑ ↓</span></div><ol id="ripple-order" class="ripple-order"></ol><p class="ripple-empty" id="ripple-empty" hidden>Choose a project above to begin.</p></section>
    <details class="ripple-assumptions" open><summary>Make it fit your project <span>Planning assumptions</span></summary><div id="ripple-assumptions"></div></details></div>
    <section class="ripple-receipt" aria-labelledby="ripple-receipt-title"><div class="ripple-receipt-top"><span>WAZOOZIE / POSSIBLE DO-OVERS</span><span id="ripple-count"></span></div><h2 id="ripple-receipt-title">The second invoice<br>you’d rather avoid.</h2><p class="ripple-not-bill">A scenario preview. No charges or dollar estimates.</p><div id="ripple-risks"></div><div class="ripple-receipt-total"><span id="ripple-total-label">Ordering conflicts to discuss</span><strong id="ripple-total">0</strong></div><button type="button" class="ripple-primary" id="ripple-fix">Fix my order ↶</button><button type="button" class="ripple-quiet" id="ripple-undo" hidden>Compare with my original order</button><p class="ripple-limit">These are conditional planning prompts. A site visit and written scopes establish the actual sequence and cost.</p></section></div>
    <div class="ripple-live" role="status" aria-live="polite" id="ripple-status"></div>
    <section class="ripple-connections" aria-labelledby="ripple-connections-title"><div class="ripple-section-heading"><div><p class="ripple-kicker">THE PART BETWEEN THE JOBS</p><h2 id="ripple-connections-title">One house. Connected decisions.</h2></div><span id="ripple-summary"></span></div><div class="ripple-connection-grid" id="ripple-connections"></div></section>
    <section class="ripple-handoff"><div><p class="ripple-kicker">GET EVERYONE ON THE SAME PAGE.</p><h2>Take this to the first conversation.</h2><p>Share the project choices and assumptions with your household or contractor. Your link contains no name, address, contact information or completed-question status.</p><div class="ripple-share-actions"><button type="button" class="ripple-primary" id="ripple-share">Copy plan link ↗</button><button type="button" class="ripple-secondary" id="ripple-copy">Copy conversation sheet</button><button type="button" class="ripple-secondary" id="ripple-download">Download sheet</button><button type="button" class="ripple-quiet" id="ripple-print">Print</button></div><label class="ripple-copy-fallback" id="ripple-fallback" hidden>Copy your plan or conversation sheet<textarea id="ripple-link" readonly></textarea></label></div><aside><h3>Meet the relevant local trades.</h3><p>You choose who to contact. Sharing a plan does not send a request or book work.</p><div id="ripple-trades"></div></aside></section>
    <div class="ripple-privacy"><span>Saved on this browser when available.</span><button type="button" class="ripple-quiet" id="ripple-forget">Forget this plan</button><a href="/privacy/">Privacy</a></div>
    </section><section class="wrap ripple-method"><h2>Why the order matters.</h2><p>A good project has more than a start date and a total. It has access, handoffs and decisions that affect the next job. This preview uses a limited set of published planning rules and your selected assumptions. It does not inspect your home, identify every issue, calculate savings or replace the trades’ own assessment.</p><details><summary>Read the planning basis</summary><ul><li><a href="https://www.energystar.gov/saveathome/heating-cooling/hvac-quality-installation" target="_blank" rel="noopener">ENERGY STAR: HVAC sizing and quality installation</a></li><li><a href="https://www.epa.gov/mold/brief-guide-mold-moisture-and-your-home" target="_blank" rel="noopener">EPA: resolve moisture and prepare surfaces before finishing</a></li><li><a href="https://www.epa.gov/lead/renovation-repair-and-painting-rrp-program-consumers" target="_blank" rel="noopener">EPA: planning work that disturbs older painted surfaces</a></li></ul><p>The access, restoration and cross-trade questions are Wazoozie editorial planning prompts. No listed business has approved this sequence for your property. For older or unknown painted surfaces, ask the contractor about appropriate assessment and lead-safe practices before disturbance.</p></details><p>For a current equipment fault, start with <a href="/help/">the problem guide</a> or contact the business directly.</p></section>
    <noscript><section class="wrap ripple-method"><h2>Before the final finish</h2><p>Confirm any window, wiring, plumbing and equipment-access work before arranging the final painting in the same area. Ask who includes patching and touch-ups in the written scope. JavaScript enables the interactive order preview; <a href="/project-kit/">the project tools</a> and <a href="/local-help/">local business contacts</a> are also available.</p></section></noscript></div>'''
    write_editorial_page(out, origin, pages, '/second-invoice/', 'The Second Invoice — preview project do-overs before you pay', 'Arrange your home projects and preview possible rework. Coordinate trades, clarify scope and share a project conversation sheet with Wazoozie.', body)
    p = out / 'second-invoice/index.html'
    p.write_text(p.read_text().replace('</head>', '<link rel="stylesheet" href="/assets/second-invoice.css"></head>').replace('</body>', '<script type="module" src="/assets/second-invoice.js"></script></body>'))
    promo = '''<section class="wrap ripple-promo" aria-labelledby="ripple-promo-title"><div><span class="ripple-kicker">NEW / THE SECOND INVOICE</span><h2 id="ripple-promo-title">“We’ll need to<br>open that again.”</h2><p>See how one home project can undo another. Rearrange your plans before you pay for a do-over.</p><a href="/second-invoice/" class="ripple-promo-link">Preview the work you could pay for twice ↗</a></div><a class="ripple-promo-demo" href="/second-invoice/"><span>YOUR PLAN</span><div><b>01</b> Paint the room <em>Done.</em></div><div><b>02</b> Replace the windows <em>The trim?</em></div><div class="ripple-promo-again"><b>↶</b> Paint the room. Again.</div><strong>What if you changed the order? →</strong></a></section>'''
    home = out / 'index.html'
    s = home.read_text()
    marker = '<section class="wrap network-intro'
    if marker in s:
        s = s.replace(marker, promo + marker, 1)
    else:
        s = s.replace('</main>', promo + '</main>', 1)
    home.write_text(s.replace('</head>', '<link rel="stylesheet" href="/assets/second-invoice.css"></head>', 1))
    for path in ('explore/index.html', 'project-kit/index.html'):
        p = out / path
        if p.exists():
            p.write_text(p.read_text().replace('</main>', '<section class="wrap ripple-tool-link"><h2>Planning more than one job?</h2><p>See which projects could undo each other, then put the right questions in front of the trades.</p><a href="/second-invoice/">Try The Second Invoice →</a></section></main>', 1))
    for p in out.rglob('*.html'):
        s = p.read_text().replace('<a href="/explore/">Tools &amp; discoveries</a>', '<a href="/explore/">Tools &amp; discoveries</a><a href="/second-invoice/">The Second Invoice</a>', 1)
        p.write_text(s)
